"""The research tree guard must recognize only exact rattler-generated files."""
import json

import pytest

from common import ScaffoldError
import opensfm_graph_policy as policy
from openmvs_graph_policy import fingerprint_tree


def test_opensfm_tree_allows_only_exact_recorded_rattler_sources(tmp_path, monkeypatch):
    tree = tmp_path / 'tree'
    tree.mkdir()
    (tree / 'CMakeLists.txt').write_text('verified')
    monkeypatch.setattr(policy, 'EXPECTED_TREE', fingerprint_tree(tree))
    sources = [
        {'url': policy.PRIMARY['url'], 'sha256': policy.PRIMARY['sha256'],
         'patches': ['patches/0001-ceres-config.patch']},
        {'url': policy.PYBIND11['url'], 'sha256': policy.PYBIND11['sha256'],
         'target_directory': policy.PYBIND11['path']},
    ]
    metadata = tree / '.source_info.json'
    metadata.write_text(json.dumps({'sources': sources}))
    for name in ('build_env.sh', 'conda_build.sh', 'conda_build.log'):
        (tree / name).write_text('generated by rattler')
    policy.verify_opensfm_tree(tree)
    sources[1]['target_directory'] = 'unreviewed'
    metadata.write_text(json.dumps({'sources': sources}))
    with pytest.raises(ScaffoldError, match='metadata'):
        policy.verify_opensfm_tree(tree)
    sources[1]['target_directory'] = policy.PYBIND11['path']
    metadata.write_text(json.dumps({'sources': sources}))
    (tree / 'build_env.sh').unlink()
    (tree / 'build_env.sh').symlink_to(tree / 'CMakeLists.txt')
    with pytest.raises(ScaffoldError, match='symlink'):
        policy.verify_opensfm_tree(tree)
